/**
 * generated by stackra gen from src/config/seo.config.ts (robots), src/routes/site/site.layout.ts
 * and context.ts — do not edit
 * Purpose: `/robots.txt` per site: one group per configured crawler with its allows and disallows,
 *          and the sitemap index link, on a live site; disallow everything on a preview host or a
 *          sandbox tenant.
 * Boundary: the groups are the config's, read from the container per request; a rule written for
 *           one crawler never applies to another (`@stackra/seo`). The site is the site
 *           layout's loader, run once for the request. A resource route with no UI and no cookie.
 * Runtime: worker
 */
import { routeContext } from "@stackra/navigation/react";
import { robotsTxt, SeoConfig } from "@stackra/seo";
import type { Route } from "./+types/robots";
import { SiteLayout } from "#src/routes/site/site.layout";
import { routeKeys } from "../context";

/** The robots groups of the site, or one group that disallows everything. */
export async function loader(args: Route.LoaderArgs) {
  const ctx = routeContext(args, routeKeys);
  const { site } = await ctx.layout(SiteLayout);
  const groups = Object.entries(ctx.config(SeoConfig).robots).map(([userAgent, group]) => ({
    userAgent,
    allow: group.allow,
    disallow: group.disallow,
  }));
  const body = site.indexable
    ? robotsTxt({ groups, sitemap: `${site.origin}/sitemap.xml` })
    : robotsTxt({ groups: [{ userAgent: "*", allow: [], disallow: ["/"] }] });
  return new Response(body, {
    headers: {
      "Content-Type": "text/plain; charset=utf-8",
      "Cache-Control": "public, max-age=3600",
    },
  });
}
